      "doc.toc.overview": "Overview",
      "doc.toc.generate": "Generate Wallet",
      "doc.toc.chain": "Chain &amp; Wallet",
      "doc.toc.jobs": "Jobs",
      "doc.toc.chat": "Chat &amp; Routing",
      "doc.toc.mcp": "MCP Servers",
      "doc.toc.search": "History Search",
      "doc.toc.explorer": "Explorer",
      "doc.toc.skills": "Skills",
