      "fw.hero.sub": "White-label, sovereign <span class=\"text-[#171717]\">AI compute</span> stablecoins",
      "fw.fund.eyebrow": "RESERVE FUNDING",
      "fw.fund.title": "Seeded by an <span class=\"neon\">offshore note.</span>",
      "fw.fund.desc": "Each coin's reserve can be seeded with privately placed notes: an offshore SPV places them with qualified international investors, 100% of the proceeds sit in a ring-fenced custodial reserve backing the coin, and the notes are serviced by compute revenue plus yield on the reserve. Coin holders never carry investor risk.",
      "fw.fund.notice": "A structure, not an offer — available to qualified institutional investors on request.",
