      "fw.hero.sub": "White-label, эгемен стейблкоиндер <span class=\"text-[#171717]\">AI эсептөө</span> үчүн",
      "fw.fund.eyebrow": "РЕЗЕРВДИ КАРЖЫЛОО",
      "fw.fund.title": "Башаты — <span class=\"neon\">офшордук нота.</span>",
      "fw.fund.desc": "Ар бир монетанын резерви жеке жайгаштырылган ноталар менен түзүлүшү мүмкүн: офшордук SPV аларды квалификациялуу эл аралык инвесторлорго жайгаштырат, каражаттын 100% монетаны камсыздаган өзүнчө кастодиалдык резервде сакталат, ал эми ноталар эсептөө кирешеси жана резервдин кирешеси менен тейленет. Монета ээлери инвестордун тобокелин эч качан көтөрбөйт.",
      "fw.fund.notice": "Бул сунуш эмес, структура — квалификациялуу институционалдык инвесторлорго суроо-талап боюнча жеткиликтүү.",
      "mnr.nav.daicoin": "DAI монета",
