      "mnr.net.eyebrow": "ИНФРАСТРУКТУРА",
      "mnr.net.title": "Эсептөө камсыздоочуларынын<br>жандуу тармагы.",
      "mnr.net.desc": "Локалдык LLM менен иштеген түйүндөр борборсуздандырылган AI эсептөө тармагын түзөт. Тапшырмалар келгенде, сенин машинаң аларды иштетип, таап турат — маалымат борбору кереги жок.",
      "mnr.app.eyebrow": "ДЕСКТОП КОЛДОНМО",
      "mnr.app.desc": "Бир нативдик колдонмо. Түйүнүң тармакка кошулат, локалдык LLM кирген AI тапшырмаларын чечет, ар бир жолу сен DAI табасың.",
      "mnr.dl.title": "Чыныгы эсептөө кошууга даярсыңбы?",
      "mnr.dl.desc": "Системаң үчүн даяр бинардык файлды жүктө. Орнотуу үчүн кош чык — техникалык эмес колдонуучуларга терминал да, код да кереги жок.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Каалаган дистрибутив",
