      "b2b.hero.eyebrow": "去中心化同主權",
      "b2b.hero": "<span class=\"neon\">去中心化。</span><br>主權。",
      "b2b.hero.sub": "你管自己用緊嘅 AI。投票決定佢做咩。喺協議層影響決策——唔係透過一間公司。",
