      "fw.hero.sub": "白標、主權嘅<span class=\"text-[#171717]\">AI 算力</span>穩定幣",
      "fw.fund.eyebrow": "儲備融資",
      "fw.fund.title": "由一張<span class=\"neon\">離岸票據</span>啟動。",
      "fw.fund.desc": "每枚幣嘅儲備可以用私募票據注資：離岸 SPV 向合格國際投資者配售，所得 100% 存放喺隔離託管儲備為幣提供支撐，票據由算力收入加上儲備收益償付。持幣人從不承擔投資者風險。",
      "fw.fund.notice": "呢個係結構，唔係要約——應合格機構投資者要求提供。",
