      "mnr.net.eyebrow": "基礎設施",
      "mnr.net.title": "一張活住嘅<br>算力提供者網絡。",
      "mnr.net.desc": "跑本地大模型嘅節點組成去中心化 AI 算力網絡。任務嚟到，你部機處理同賺錢——唔使數據中心。",
      "mnr.app.eyebrow": "桌面應用",
