      "fw.hero.sub": "Stablecoins white-label y soberanas de <span class=\"text-[#171717]\">cómputo IA</span>",
      "fw.fund.eyebrow": "FINANCIACIÓN DE LA RESERVA",
      "fw.fund.title": "Sembrada con una <span class=\"neon\">nota offshore.</span>",
      "fw.fund.desc": "La reserva de cada moneda puede sembrarse con notas colocadas de forma privada: una SPV offshore las coloca entre inversores internacionales cualificados, el 100% de lo recaudado permanece en una reserva segregada en custodia que respalda la moneda, y las notas se atienden con los ingresos de cómputo más el rendimiento de la propia reserva. Los tenedores de la moneda nunca cargan con el riesgo del inversor.",
      "fw.fund.notice": "Una estructura, no una oferta — disponible bajo petición para inversores institucionales cualificados.",
      "mnr.nav.daicoin": "Moneda DAI",
      "mnr.hero.title": "Impulsa el cerebro IA.<br><span class=\"neon\">Gana cuando no estás.</span>",
      "mnr.hero.cta1": "Ejecuta un nodo",
      "mnr.hero.cta2": "Ver la malla en vivo",
      "mnr.net.eyebrow": "LA INFRAESTRUCTURA",
      "mnr.net.title": "Una malla viva de<br>proveedores de cómputo.",
      "mnr.net.desc": "Los nodos que ejecutan LLM locales forman una red de cómputo IA descentralizada. Cuando llegan tareas, tu máquina las procesa y gana — sin centro de datos.",
      "mnr.app.eyebrow": "LA APP DE ESCRITORIO",
      "mnr.app.desc": "Una sola app nativa. Tu nodo se une a la red, tu LLM local resuelve las tareas de IA entrantes y ganas DAI cada vez.",
      "mnr.dl.title": "¿Listo para aportar cómputo real?",
      "mnr.dl.desc": "Descarga el binario precompilado para tu sistema. Doble clic para instalar — sin terminal ni código para usuarios no técnicos.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Cualquier distro",
      "mnr.dl.linux.desc": "AppImage portátil — un solo archivo, funciona en cualquier distro. Descarga → chmod +x → doble clic o ejecuta desde cualquier lugar. Sin instalación root.",
      "mnr.dl.linux.btn1": "Descargar AppImage (x64)",
      "mnr.dl.linux.btn2": "Descargar AppImage (ARM64)",
      "mnr.dl.mac.desc": "Abre el .dmg → arrastra a Applications • puede que necesites «Open Anyway» en Security & Privacy",
      "mnr.dl.mac.btn1": "Descargar .dmg Apple Silicon",
      "mnr.dl.mac.btn2": "Descargar instalador .dmg Intel",
      "mnr.dl.win.desc": "Instalador .exe estándar con accesos directos, entrada en el menú Inicio y desinstalador limpio. Hecho con NSIS.",
      "mnr.dl.win.btn": "Descargar instalador de Windows",
      "mnr.dl.power.title": "Usuarios avanzados e instalación en una línea",
      "mnr.dl.power.link1": "Descargar easy-start.sh",
      "mnr.dl.power.link2": "download-latest.sh (elige el binario)",
      "mnr.dl.power.link3": "Ver scripts de compilación + código fuente",
      "mnr.wal.eyebrow": "APP COMPLEMENTARIA",
      "mnr.wal.title": "Billetera DAI Miner",
      "mnr.wal.sub": "Envía, recibe y sigue tus recompensas de minería en tiempo real — directamente desde tu teléfono.",
      "mnr.wal.f1t": "Saldo en vivo",
      "mnr.wal.f1d": "Saldo en tiempo real obtenido de tu nodo activo mediante la ligera Wallet API.",
      "mnr.wal.f2t": "Enviar y recibir",
      "mnr.wal.f2d": "Transferencias DAI completas entre direcciones. Funciona con cualquier nodo que conozca la billetera.",
      "mnr.wal.f3t": "Historial de transacciones",
