      "fw.hero.sub": "Des stablecoins white-label et souverains pour le <span class=\"text-[#171717]\">calcul IA</span>",
      "fw.fund.eyebrow": "FINANCEMENT DE LA RÉSERVE",
      "fw.fund.title": "Amorcée par une <span class=\"neon\">note offshore.</span>",
      "fw.fund.desc": "La réserve de chaque coin peut être amorcée par des notes placées en privé : une SPV offshore les place auprès d'investisseurs internationaux qualifiés, 100 % des fonds restent dans une réserve cantonnée chez un dépositaire qui adosse le coin, et les notes sont servies par les revenus du calcul plus le rendement de la réserve. Les détenteurs du coin ne portent jamais le risque investisseur.",
      "fw.fund.notice": "Une structure, pas une offre — disponible sur demande pour les investisseurs institutionnels qualifiés.",
