      "fw.fund.desc": "প্রতিটি কয়েনের রিজার্ভ ব্যক্তিগতভাবে ইস্যু করা নোটের মাধ্যমে গঠন করা যায়: একটি অফশোর SPV সেগুলো যোগ্য আন্তর্জাতিক বিনিয়োগকারীদের কাছে ইস্যু করে, প্রাপ্ত অর্থের 100% কয়েনের সমর্থনকারী একটি পৃথক কাস্টডিয়াল রিজার্ভে থাকে, এবং নোটগুলো পরিশোধ করা হয় কম্পিউট আয় ও রিজার্ভের মুনাফা থেকে। কয়েনধারীরা কখনোই বিনিয়োগকারীর ঝুঁকি বহন করেন না।",
