      "mnr.net.desc": "স্থানীয় LLM চালানো নোডগুলো মিলে একটি বিকেন্দ্রীভূত AI কম্পিউট নেটওয়ার্ক তৈরি করে। কাজ এলে আপনার মেশিন সেগুলো প্রক্রিয়া করে এবং আয় করে — কোনো ডেটা সেন্টার লাগে না।",
