      "blog.p1.date": "یکم ستمبر 2026 · v0.4.34",
      "blog.p1.title": "ہم نے اپنا نام بدلا۔ اور اس کے نیچے تقریباً <span class=\"neon\">سب کچھ</span> بھی۔",
      "blog.p1.excerpt": "‏Proof of Human اب DAI ہے — Decentralized Artificial Intelligence۔ 0.4.2 اور 0.4.34 کے درمیان نیٹ ورک نے یہ بھی سیکھا کہ بغیر کسی سیٹ اپ کے کسی بھی مشین پر AI چلائے، مائنرز کو اُس کام کا معاوضہ دے جو انہوں نے واقعی کیا، 14 مقامی کرنسیاں اٹھائے، اور نوڈز کو بغیر بیچ والے کے براہِ راست جوڑے۔ یہ وہ پانچ تبدیلیاں ہیں جن کے لیے اپ ڈیٹ کرنا بنتا ہے۔",
