      "doc.search.suggest": "انڈیکس شدہ بلاک چین کام کی تاریخ سے خودکار تکمیل — پرانے پرامپٹس اور جوابات کے ٹکڑے۔",
      "doc.search.match": "جب پرامپٹ پہلے کی آن چین تاریخ سے قریبی مماثل ہو تو مکمل محفوظ جواب واپس کریں (مماثلت ≥ 0.86)۔",
