      "doc.hf.download": "Hugging Face ID سے ڈیٹاسیٹ انسٹال کریں۔ HF تک رسائی نہ ہو تو کسی پیئر مائنر سے کھینچ لیتا ہے۔ کامیابی پر <code>{ ok: true, manifest }</code> واپس کرتا ہے۔",
