      "doc.p2p.currencies": "معاون مظنے اور آن چین بنیادی اثاثے۔ KGST اور USDT مسیر شامل ہیں۔",
      "doc.p2p.markets": "آخری قیمت (کھلی بک کا وسط) اور 24 گھنٹے کی تبدیلی کے ساتھ جوڑوں کی فہرست۔ تاریخ موجود نہ ہونے تک <code>change24h</code> <code>null</code> رہتا ہے۔ اختیاری <code>?pair=BASE-QUOTE</code> (مثلاً <code>KGST-USDT-TRC20</code>)۔",
