      "doc.errors.json": "جوابات JSON ہیں۔ خرابیاں مناسب HTTP اسٹیٹس (400، 401، 402، 404، 500) کے ساتھ <code>{ \"error\": \"message\" }</code> واپس کرتی ہیں۔",
      "doc.errors.payment": "<strong class=\"text-[#171717]\">ادائیگی درکار (402):</strong> بغیر درست دستخط شدہ <code>paymentTx</code> کے اسکل/کمپیوٹ کام چلانے سے پہلے ہی مسترد ہو جاتے ہیں۔",
      "doc.errors.signing": "<strong class=\"text-[#171717]\">دستخط:</strong> اپنی ed25519 کلید <code>/api/wallet/register-key</code> کے ذریعے رجسٹر کریں، پھر <code>jobId + minerWallet + maxBudget + nonce</code> کو جوڑ کر ادائیگی کے ثبوت دستخط کریں۔",
      "doc.errors.sdks": "<strong class=\"text-[#171717]\">SDKs:</strong> دستخط خودکار طور پر سنبھالنے کے لیے <a href=\"https://github.com/Proof-of-Human-Network/poh-miner\" class=\"neon hover:underline\">dai-miner SDK</a> میں <code>runCompute()</code> / <code>submitJob()</code> استعمال کریں۔",
      "doc.foot.tag": "DAI مائنر نیٹ ورک API — ڈیفالٹ پورٹ 3456",
      "doc.foot.landing": "لینڈنگ",
      "doc.assets.title": "اسٹیبل کوائنز اور کثیر کرنسی",
      "doc.assets.p1": "DAI کے ساتھ DAI چین پر چودہ علاقائی اسٹیبل کوائنز چلتے ہیں: <strong>KGST</strong> (کرغزستان سوم، DAI/BSC/Tron پر پل شدہ) نیز <strong>αιETB, αιBTN, αιVES, αιPYG, αιBDT, αιPKR, αιEGP, αιIQD, αιAOA, αιCUP, αιLYD, αιSDG, αιIRR</strong> (وائر ٹکرز <code>aiETB</code>, <code>aiBTN</code>, <code>aiVES</code>, <code>aiPYG</code>, <code>aiBDT</code>, <code>aiPKR</code>, <code>aiEGP</code>, <code>aiIQD</code>, <code>aiAOA</code>, <code>aiCUP</code>, <code>aiLYD</code>, <code>aiSDG</code>, <code>aiIRR</code>)۔ سب <strong>2 اعشاریہ</strong> استعمال کرتے ہیں (1 اکائی = 100 raw)؛ DAI 9 رکھتا ہے (1&nbsp;DAI&nbsp;=&nbsp;1e9&nbsp;μDAI)۔ آف چین آن ریمپس: <strong>USDT</strong> (<code>USDT-ERC20</code>، <code>USDT-TRC20</code>، <code>USDT-TON</code>، <code>USDT-SOL</code>، <code>USDT-BEP20</code>)، <strong>USDC</strong> اور بینک ٹرانسفر۔",
      "doc.assets.p2": "GET /api/assets ہر آن چین اثاثے کو اس کے اعشاریوں، ظاہری ناموں اور فی کرنسی گیس قیمتوں کے ساتھ درج کرتا ہے۔ GET /api/wallet/balance ایک اضافی assets نقشہ واپس کرتا ہے جس میں ہر اسٹیبل کوائن کا raw اور ظاہری بیلنس ہوتا ہے۔",
      "doc.assets.p3": "منتقلیاں: POST /api/wallet/send (اور /api/tx/submit) ایک currency فیلڈ قبول کرتے ہیں — DAI کے لیے اسے چھوڑ دیں۔ لین دین کے دستخط شدہ ہیش میں currency صرف اُس وقت شامل ہوتا ہے جب وہ DAI نہ ہو، سو موجودہ DAI لین دین اور دستخط بغیر تبدیلی درست رہتے ہیں۔",
      "doc.jobs.pricing.currency": "کام کی فیس DAI یا کسی بھی آن چین اسٹیبل کوائن میں ادا کی جا سکتی ہے: کام کے پے لوڈ میں currency مقرر کریں۔ فیس کی کم سے کم حد فی کرنسی طے ہوتی ہے، اور مائنر کو بالکل وہی کرنسی ملتی ہے جو ادا کی گئی — کوئی تبادلہ نہیں۔",
      "doc.p2p.swap": "آن چین DAI اثاثے (<code>DAI</code>، <code>aiETB</code>، <code>aiBTN</code>، <code>aiBDT</code>، <code>aiPKR</code>، …) اور پل شدہ <code>KGST</code> (DAI/BSC/Tron) بنیاد کے طور پر تجارت کرتے ہیں۔ جب دونوں طرف DAI پر تصفیہ ہو (مثلاً <code>KGST/aiBDT</code> یا <code>DAI/aiETB</code>) تو تجارت ایک ہی قدم میں <strong>ایٹمی طور پر</strong> طے ہو جاتی ہے — ادائیگی بھیجنے/تصدیق کا مرحلہ نہیں؛ رقم سیدھی ٹیکر کے dai پتے پر جاتی ہے۔ آف چین اطراف (USDT، USDC، بینک ٹرانسفر) دستی ایسکرو بہاؤ برقرار رکھتے ہیں۔",
