      "exp.search.btn": "ፈልግ",
      "exp.search.hint": "ጠቃሚ ምክር፦ ቀሪ ሒሳቡን፣ ዝውውሮቹንና ሥራዎቹን ለማየት <span class=\"mono\">dai…</span> አድራሻ ይለጥፉ።",
      "exp.tab.blocks": "ብሎኮች",
