      "exp.jobs": "የተጠናቀቁ ሥራዎች",
      "exp.recenttx": "የቅርብ ጊዜ ግብይቶች",
      "fw.hero.sub": "ኋይት-ሌብል፣ ሉዓላዊ <span class=\"text-[#171717]\">የAI ስሌት</span> ስቴብልኮይኖች",
      "fw.fund.eyebrow": "የመጠባበቂያ ፈንድ",
      "fw.fund.title": "በ<span class=\"neon\">የባህር ማዶ ኖት</span> የተጀመረ።",
      "fw.fund.desc": "የእያንዳንዱ ሳንቲም መጠባበቂያ በግል በሚቀርቡ ኖቶች ሊጀመር ይችላል፦ የባህር ማዶ SPV ለብቁ ዓለም አቀፍ ባለሀብቶች ያቀርባቸዋል፣ 100% ገቢው ሳንቲሙን በሚደግፍ የተለየ የአደራ መጠባበቂያ ውስጥ ይቀመጣል፣ ኖቶቹም በስሌት ገቢና በመጠባበቂያው ትርፍ ይከፈላሉ። የሳንቲም ባለቤቶች የባለሀብቱን ስጋት አይሸከሙም።",
      "fw.fund.notice": "መዋቅር እንጂ ቅናሽ አይደለም — በጥያቄ ለብቁ ተቋማዊ ባለሀብቶች ይቀርባል።",
      "mnr.nav.daicoin": "DAI ሳንቲም",
      "mnr.hero.title": "የAI አእምሮን ያንቀሳቅሱ።<br><span class=\"neon\">እርስዎ ውጭ ሲሆኑም ያገኛል።</span>",
      "mnr.hero.cta1": "አንጓ ማስኬድ ይጀምሩ",
      "mnr.hero.cta2": "ቀጥታ መረቡን ይመልከቱ",
      "mnr.net.eyebrow": "መሠረተ ልማቱ",
      "mnr.net.title": "የስሌት አቅራቢዎች<br>ሕያው መረብ።",
      "mnr.net.desc": "የአካባቢ LLM የሚያስኪዱ አንጓዎች ያልተማከለ የAI ስሌት አውታረ መረብ ይመሠርታሉ። ተግባራት ሲመጡ ማሽንዎ ያስኬዳቸዋል እና ያገኛል — ዳታ ማዕከል አያስፈልግም።",
      "mnr.app.eyebrow": "የዴስክቶፕ መተግበሪያ",
      "mnr.app.desc": "አንድ ኔቲቭ መተግበሪያ። አንጓዎ አውታረ መረቡን ይቀላቀላል፣ የአካባቢ LLMዎ የሚመጡ የAI ተግባራትን ይፈታል፣ በእያንዳንዱ ጊዜም DAI ያገኛሉ።",
      "mnr.dl.title": "እውነተኛ ስሌት ለማበርከት ዝግጁ ነዎት?",
      "mnr.dl.desc": "ለሲስተምዎ የተዘጋጀውን ባይነሪ ያውርዱ። ለመጫን ሁለቴ ይጫኑ — ለቴክኒክ ላልሆኑ ተጠቃሚዎች ተርሚናልም ሆነ ኮድ አያስፈልግም።",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • ማንኛውም ዲስትሮ",
      "mnr.dl.linux.desc": "ተንቀሳቃሽ AppImage — አንድ ፋይል፣ በማንኛውም ዲስትሮ ይሠራል። ያውርዱ → chmod +x → ሁለቴ ይጫኑ ወይም ከየትም ያስኪዱ። የroot ጭነት አያስፈልግም።",
      "mnr.dl.linux.btn1": "AppImage ያውርዱ (x64)",
      "mnr.dl.linux.btn2": "AppImage ያውርዱ (ARM64)",
      "mnr.dl.mac.desc": ".dmg ይክፈቱ → ወደ Applications ይጎትቱ • በSecurity & Privacy ውስጥ “Open Anyway” ሊያስፈልግ ይችላል",
      "mnr.dl.mac.btn1": "Apple Silicon .dmg ያውርዱ",
      "mnr.dl.mac.btn2": "Intel .dmg መጫኛ ያውርዱ",
