      "exp.loading": "མངོན་གསལ་འབད་བཞིན་ཡོད…",
      "exp.loadingblock": "བློཀ་མངོན་གསལ་འབད་བཞིན་ཡོད…",
      "exp.searching": "འཚོལ་ཞིབ་འབད་བཞིན་ཡོད…",
      "exp.noblocks": "ད་ལྟོ་ཚུན་བློཀ་མེད།",
